from pathlib import Path
import json,subprocess,httpx,base64,concurrent.futures
O=Path(__file__).resolve().parent;ROOT=O.parents[5];key=next(l.split('=',1)[1].strip().strip('"').strip("'") for l in (ROOT/'.env').read_text().splitlines() if l.startswith('GEMINI_API_KEY='))
def work(pair):
 name,path=pair;f=O/(name+'-sound.mp3');subprocess.run(['ffmpeg','-v','error','-y','-i',str(path),'-vn','-ac','1','-ar','24000','-b:a','64k',str(f)],check=True)
 prompt='Analyze this entire actual ad audio for EDITING STYLE ONLY, not health accuracy or transcript. Identify foreground speech delivery and pace, presence/absence of background music with concrete audible features, sound effects and transitions (timestamps), room ambience, silence patterns and speech edits. Do not invent music when only voice is audible. Return JSON: speech_style, background_music {present,confidence,description,time_ranges}, sound_effects [timestamp,description,confidence], notable_edits, mix_description, limitations. If uncertain distinguish music from noise.'
 r=httpx.post('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-pro:generateContent',headers={'x-goog-api-key':key},json={'contents':[{'parts':[{'inline_data':{'mime_type':'audio/mpeg','data':base64.b64encode(f.read_bytes()).decode()}},{'text':prompt}]}],'generationConfig':{'temperature':.1,'responseMimeType':'application/json'}},timeout=240);r.raise_for_status();j=r.json();z=''.join(t.get('text','') for a in j['candidates'] for t in a['content']['parts']);(O/(name+'-sound-analysis.json')).write_text(z);print(name,z,flush=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:list(ex.map(work,[('Alicia-Pro-Full',O.parent/'reference-analysis/alicia-darling-reference.mp4'),('NU021-Pro-Full',O/'NU021.mp4')]))
